 'support low':(f"{wv['Valuation']['B16'].value:.2f}" in memo,wv['Valuation']['B16'].value),
 'support mid':(f"{wv['Valuation']['C16'].value:.2f}" in memo,wv['Valuation']['C16'].value),
 'support high':(f"{wv['Valuation']['D16'].value:.2f}" in memo,wv['Valuation']['D16'].value),
