 'full post':(f"{wv['Dilution']['C8'].value:.6f}" in memo,wv['Dilution']['C8'].value),
}
print('MEMO_CROSS',checks)
for k,(ok,val) in checks.items():
 if not ok: issues.append(('memo_cross',k,val))
