expected={'B12':wv['Offering_Proceeds']['B10'].value*wv['Offering_Proceeds']['B11'].value,'C12':wv['Offering_Proceeds']['C10'].value*wv['Offering_Proceeds']['C11'].value,'B14':wv['Offering_Proceeds']['B10'].value-wv['Offering_Proceeds']['B12'].value-wv['Offering_Proceeds']['B13'].value,'C14':wv['Offering_Proceeds']['C10'].value-wv['Offering_Proceeds']['C12'].value-wv['Offering_Proceeds']['C13'].value}
print('OFFERING_EXPECT',expected)
for c,e in expected.items():
 if not math.isclose(wv['Offering_Proceeds'][c].value,e,abs_tol=1e-10):issues.append(('offer_cache',c,wv['Offering_Proceeds'][c].value,e))
# tieout formula and cache
for r in range(5,32):
 for col in 'CDE':
  if wf['Tieout_Detail'][f'{col}{r}'].data_type!='f':issues.append(('tie_formula',f'{col}{r}'))
