 c=wv['Tieout_Detail'][f'C{r}'].value;d=wv['Tieout_Detail'][f'D{r}'].value;e=wv['Tieout_Detail'][f'E{r}'].value
 if not math.isclose(float(e),float(c)-float(d),abs_tol=1e-10):issues.append(('tie_cache',r,c,d,e))
# filename/path and support source references exists where path-like
st=list(csv.DictReader((out/'FIN3-WKN-152_source_trace.csv').open(encoding='utf-8-sig')))
missing=[]
for row in st:
 for fld in ('adopted_source','competing_source'):
  txt=row[fld]
  for m in re.findall(r'/app/input_files/[^;]+?(?=::|;|$)',txt):
   # This regexp may include explanatory suffix; only strict candidates
   p=Path(m.strip())
   if p.suffix and not p.exists():missing.append((row['item'],fld,str(p)))
print('TRACE_MISSING_STRICT',missing)
# output exact names
expected_names={'FIN3-WKN-152_ipo_model.xlsx','FIN3-WKN-152_pricing_memo.md','FIN3-WKN-152_reproduce.py','FIN3-WKN-152_qoe_bridge.csv','FIN3-WKN-152_valuation_matrix.csv','FIN3-WKN-152_source_trace.csv','FIN3-WKN-152_charts.png'}
actual={p.name for p in out.iterdir() if p.is_file()}
if actual!=expected_names:issues.append(('files',actual-expected_names,expected_names-actual))
# Read-only reproducibility script compile only, no execute (compile to /tmp)
import py_compile
py_compile.compile(str(out/'FIN3-WKN-152_reproduce.py'),cfile='/tmp/FIN3-WKN-152_reproduce.pyc',doraise=True)
print('PY_COMPILE','PASS')
